import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';

interface Manutencao {
  id: number;
  titulo: string;
  local: string;
  setor: string;
  descricao: string;
  prioridade: 'alta' | 'media' | 'baixa';
  status: 'a_fazer' | 'em_andamento' | 'concluida';
  data_criacao: string;
}

interface ManutencoesPorStatus {
  a_fazer: Manutencao[];
  em_andamento: Manutencao[];
  concluida: Manutencao[];
}

export default function TecnicoDashboard() {
  const { token } = useParams<{ token: string }>();
  const navigate = useNavigate();
  const [tecnico, setTecnico] = useState<{ nome: string; email: string } | null>(null);
  const [manutencoes, setManutencoes] = useState<ManutencoesPorStatus>({
    a_fazer: [],
    em_andamento: [],
    concluida: []
  });
  const [mensagem, setMensagem] = useState<{ tipo: 'sucesso' | 'erro'; texto: string } | null>(null);

  useEffect(() => {
    if (!token) {
      navigate('/');
      return;
    }

    const validarAcesso = async () => {
      try {
        const response = await axios.get(`http://localhost:3001/api/tecnicos/acesso/${token}`);
        setTecnico(response.data);
        carregarManutencoes();
      } catch (error) {
        navigate('/');
      }
    };

    validarAcesso();
  }, [token, navigate]);

  const carregarManutencoes = async () => {
    try {
      const response = await axios.get(`http://localhost:3001/api/tecnicos/manutencoes/${token}`);
      
      // Organizar manutenções por status
      const porStatus: ManutencoesPorStatus = {
        a_fazer: [],
        em_andamento: [],
        concluida: []
      };

      response.data.forEach((manutencao: Manutencao) => {
        porStatus[manutencao.status].push(manutencao);
      });

      setManutencoes(porStatus);
    } catch (error) {
      console.error('Erro ao carregar manutenções:', error);
    }
  };

  const handleAtualizarStatus = async (id: number, novoStatus: 'a_fazer' | 'em_andamento' | 'concluida') => {
    try {
      await axios.patch(`http://localhost:3001/api/tecnicos/manutencoes/${token}/${id}/status`, {
        status: novoStatus
      });
      
      setMensagem({ 
        tipo: 'sucesso', 
        texto: `Manutenção atualizada para ${
          novoStatus === 'a_fazer' ? 'A Fazer' : 
          novoStatus === 'em_andamento' ? 'Em Andamento' : 
          'Concluída'
        }!` 
      });
      
      carregarManutencoes();
    } catch (error) {
      setMensagem({ tipo: 'erro', texto: 'Erro ao atualizar status da manutenção' });
    }
  };

  const getPrioridadeClasses = (prioridade: string) => {
    switch (prioridade) {
      case 'alta':
        return 'border-red-200 bg-red-50';
      case 'media':
        return 'border-yellow-200 bg-yellow-50';
      case 'baixa':
        return 'border-green-200 bg-green-50';
      default:
        return 'border-gray-200 bg-gray-50';
    }
  };

  const renderManutencao = (manutencao: Manutencao) => (
    <div
      key={manutencao.id}
      className={`border rounded-lg p-4 ${getPrioridadeClasses(manutencao.prioridade)}`}
    >
      <div className="flex justify-between items-start">
        <div>
          <h3 className="font-medium">{manutencao.titulo}</h3>
          <p className="text-sm text-gray-600">Local: {manutencao.local}</p>
          <p className="text-sm text-gray-600">Setor: {manutencao.setor}</p>
          {manutencao.descricao && (
            <p className="text-sm text-gray-600 mt-2">{manutencao.descricao}</p>
          )}
          <p className="text-sm text-gray-500 mt-2">
            Data: {new Date(manutencao.data_criacao).toLocaleDateString()}
          </p>
          <p className="text-sm font-medium mt-2">
            Prioridade: <span className={`
              ${manutencao.prioridade === 'alta' ? 'text-red-600' : 
                manutencao.prioridade === 'media' ? 'text-yellow-600' : 
                'text-green-600'}
            `}>
              {manutencao.prioridade.charAt(0).toUpperCase() + manutencao.prioridade.slice(1)}
            </span>
          </p>
        </div>
        <div className="flex flex-col space-y-2">
          {manutencao.status !== 'em_andamento' && (
            <button
              onClick={() => handleAtualizarStatus(manutencao.id, 'em_andamento')}
              className="px-4 py-2 text-sm text-white bg-blue-600 rounded hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
            >
              Iniciar
            </button>
          )}
          {manutencao.status !== 'concluida' && manutencao.status === 'em_andamento' && (
            <button
              onClick={() => handleAtualizarStatus(manutencao.id, 'concluida')}
              className="px-4 py-2 text-sm text-white bg-green-600 rounded hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500"
            >
              Concluir
            </button>
          )}
        </div>
      </div>
    </div>
  );

  if (!tecnico) {
    return null;
  }

  return (
    <div className="min-h-screen bg-gray-100">
      <nav className="bg-white shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16">
            <div className="flex items-center">
              <h1 className="text-xl font-semibold text-gray-900">
                Painel do Técnico - {tecnico.nome}
              </h1>
            </div>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
        {mensagem && (
          <div className={`mb-4 rounded-md p-4 ${
            mensagem.tipo === 'sucesso' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'
          }`}>
            <p className="text-sm">{mensagem.texto}</p>
          </div>
        )}

        <div className="space-y-6">
          {/* A Fazer */}
          <div className="bg-white shadow rounded-lg p-6">
            <h2 className="text-lg font-medium text-gray-900 mb-4">
              A Fazer ({manutencoes.a_fazer.length})
            </h2>
            <div className="space-y-4">
              {manutencoes.a_fazer.map(renderManutencao)}
              {manutencoes.a_fazer.length === 0 && (
                <p className="text-sm text-gray-500 italic">Nenhuma manutenção pendente</p>
              )}
            </div>
          </div>

          {/* Em Andamento */}
          <div className="bg-white shadow rounded-lg p-6">
            <h2 className="text-lg font-medium text-blue-600 mb-4">
              Em Andamento ({manutencoes.em_andamento.length})
            </h2>
            <div className="space-y-4">
              {manutencoes.em_andamento.map(renderManutencao)}
              {manutencoes.em_andamento.length === 0 && (
                <p className="text-sm text-gray-500 italic">Nenhuma manutenção em andamento</p>
              )}
            </div>
          </div>

          {/* Concluídas */}
          <div className="bg-white shadow rounded-lg p-6">
            <h2 className="text-lg font-medium text-green-600 mb-4">
              Concluídas ({manutencoes.concluida.length})
            </h2>
            <div className="space-y-4">
              {manutencoes.concluida.map(renderManutencao)}
              {manutencoes.concluida.length === 0 && (
                <p className="text-sm text-gray-500 italic">Nenhuma manutenção concluída</p>
              )}
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}
